from datetime import datetime

class EmailClient:
    MAX_CAPACITY = 100  # Example symbolic constant; adjust as needed

    def __init__(self, addr, capacity) -> None:
        self._addr = addr
        self._capacity = capacity
        self._inbox = []

    @property
    def addr(self):
        return self._addr

    @addr.setter
    def addr(self, value):
        self._addr = value

    @property
    def capacity(self):
        return self._capacity

    @capacity.setter
    def capacity(self, value):
        self._capacity = value

    @property
    def inbox(self):
        return self._inbox

    @inbox.setter
    def inbox(self, value):
        self._inbox = value

    def send_to(self, recv, content, size):
        if not recv.is_full_with_one_more_email(size):
            self._deliver_email(recv, content, size)
            return True
        else:
            self._clear_inbox_to_make_space(size)
            return False

    def _deliver_email(self, recv, content, size):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        email = {
            "sender": self._addr,
            "receiver": recv.addr,
            "content": content,
            "size": size,
            "time": timestamp,
            "state": "unread"
        }
        recv.inbox.append(email)

    def fetch(self):
        for email in self._inbox:
            if email['state'] == "unread":
                email['state'] = "read"
                return email
        return None

    def is_full_with_one_more_email(self, size):
        return self._get_occupied_size() + size > self._capacity

    def _get_occupied_size(self):
        return sum(email["size"] for email in self._inbox)

    def _clear_inbox_to_make_space(self, size):
        if not self._addr:
            return
        freed_space = 0
        while freed_space < size and self._inbox:
            email = self._inbox.pop(0)
            freed_space += email['size']
